#include <bits/stdc++.h>
using namespace std;

long long t(int n, int h, vector<vector<long long>>& dp) {
    if (dp[n][h] == -1) {
        long long total = 0;
        for (int m = 1; m <= n; ++m) {
            long long sum1 = 0;
            for (int i = 0; i < h; ++i) {
                sum1 += t(m - 1, i, dp);
            }
            long long sum2 = 0;
            for (int i = 0; i < h; ++i) {
                sum2 += t(n - m, i, dp);
            }
            total += t(m - 1, h - 1, dp) * sum1 + t(n - m, h - 1, dp) * sum2;
        }
        dp[n][h] = total;
    }
    return dp[n][h];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, h;
    cin >> n >> h;

    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, -1));
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= n; ++j) {
            if (i == 0 && j == 0) {
                dp[i][j] = 1;
            } else if (i == 0 || j == 0) {
                dp[i][j] = 0;
            } else {
                // initialize with -1, will be computed in t()
                dp[i][j] = -1;
            }
        }
    }

    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= n; ++j) {
            t(i, j, dp);
        }
    }

    long long result = 0;
    for (int i = h; i <= n; ++i) {
        result += dp[n][i];
    }
    cout << result << "\n";

    return 0;
}
